const FAMILIES = RAW_FAMILIES.map(f => ({ ...f, designs: f.designs.map(d => { d.id = proceduralId(d.id); return d; }) }));
// every vehicle OpenTTD can hold states its OpenTTD facts in one table (openttdTable.ts),
// put on the design here, so no source module (and none of its JS models) changes for them
for (const f of FAMILIES) {
  if (f.meta !== "vehicles") continue;
  for (const d of f.designs) if (OPENTTD_TABLE[d.id]) d.openttd = OPENTTD_TABLE[d.id];
}
/** Every village house (village.meta.json). */
export const VILLAGE_DESIGNS: readonly ProceduralDesign[] = FAMILIES.filter(f => f.meta === "village").flatMap(f => f.designs);

/** Every building design: the skyscrapers, then the landmarks and stations (skyscrapers.meta.json). */
export const BUILDINGS: readonly ProceduralDesign[] = FAMILIES.filter((f) => f.meta === "buildings").flatMap((f) => f.designs);

/** Every vehicle design: road, rail, air, water and rope (vehicles.meta.json). */
export const ALL_VEHICLES: readonly ProceduralDesign[] = FAMILIES.filter((f) => f.meta === "vehicles").flatMap((f) => f.designs);

/** Every tree species (trees.ts, listed in woods.meta.json). */
export const TREE_DESIGNS: readonly ProceduralDesign[] = FAMILIES.filter((f) => f.meta === "trees").flatMap((f) => f.designs);

/** Every woods type as a grove model (woodsModels.ts), for the site. */
export const WOODS_DESIGNS: readonly ProceduralDesign[] = FAMILIES.filter((f) => f.meta === "woods").flatMap((f) => f.designs);

/** Every prop the game places on its structures (props.meta.json; props/propKit.ts). */
export const PROP_DESIGNS: readonly ProceduralDesign[] = FAMILIES.filter((f) => f.meta === "props").flatMap((f) => f.designs);

/** Every character (characters.meta.json; characters.ts). */
export const CHARACTER_DESIGNS: readonly ProceduralDesign[] = FAMILIES.filter((f) => f.meta === "characters").flatMap((f) => f.designs);

/** The site's preview designs, one per set type, block type and texture (previews/index.ts); in no game meta. */
export const PREVIEW_DESIGNS: readonly ProceduralDesign[] = FAMILIES.filter((f) => f.meta === "previews").flatMap((f) => f.designs);

/** Every design, by id: the buildings, the village houses (village.meta.json), the vehicles, the trees, the woods groves, the props, the set previews, then the characters (last, so the
 * test shards, which split this order, keep every older design where it was). */
export const DESIGNS: ReadonlyMap<string, ProceduralDesign> = new Map([...BUILDINGS, ...VILLAGE_DESIGNS, ...ALL_VEHICLES, ...TREE_DESIGNS, ...WOODS_DESIGNS, ...PROP_DESIGNS, ...PREVIEW_DESIGNS, ...CHARACTER_DESIGNS].map((d) => [d.id, d]));

const VEHICLE_IDS = new Set(ALL_VEHICLES.map((d) => d.id));

/** A design's catalog fields: its own, else its family's (the vehicles' or the skyscrapers'). */
export function catalogFields(design: ProceduralDesign): CatalogFields {
  return design.catalog ?? (VEHICLE_IDS.has(design.id) ? VEHICLE_CATALOG : SKYSCRAPER_CATALOG);
}

/** The generator module that exports each design's build function (the JS bundle's entry). */
const DESIGN_SOURCE = new Map<string, string>(FAMILIES.flatMap((f) => f.designs.map((d) => [d.id, f.source] as const)));

/** The generator module exporting a design's build function. Throws on an unknown id. */
export function designSource(id: string): string {
  const source = DESIGN_SOURCE.get(id);
  if (!source) throw new Error(`no procedural model "${id}"`);
  return source;
}

/**
 * A built design's GLB bytes. The generator string is part of the bytes; a
 * skyscraper's matches what the webapp's copy wrote, so a model built here is
 * byte-identical to one built there.
 */
export function toGlb(id: string, model: MeshBuilder): Uint8Array {
  return VEHICLE_IDS.has(id)
    ? model.toGlb(`Rail Island procedural vehicle (${id})`, "vehicle")
    : model.toGlb(`Rail Island procedural building (${id})`);
}

/** The GLB bytes of one design, built with `params` (defaults when absent). Throws on an unknown id. */
export function designGlb(id: string, params?: ParamValues): Uint8Array {
  const design = DESIGNS.get(id);
  if (!design) throw new Error(`no procedural model "${id}"`);
  return toGlb(id, design.build(params));
}

/**
 * Checks a design's OpenTTD block (design.ts checkOpenttdProperties): required on
 * every vehicle a GRF can hold; and each formation fits OpenTTD's part cap, its
 * cars measured on their built models.
 */
export function checkOpenttdDesign(
  design: ProceduralDesign,
  // a car's length along x, metres: measured on its built model unless the build cache knows it
  carLength: (params: ParamValues) => number = (params) => {
    const stats = glbStats(toGlb(design.id, design.build(params)));
    return stats.max[0] - stats.min[0];
  },
): void {
  const vehicle = VEHICLE_IDS.has(design.id);
  const feature = vehicle ? openttdFeatureOf(catalogFields(design)) : null;
  checkOpenttdProperties(design, vehicle, feature);
  if (feature && !idsOf(design, feature)) {
    throw new Error(`${design.id}: generator/openttdIds.json gives it no OpenTTD ids, or a retired one - run \`pnpm openttd:ids\` and commit the file (docs/site/openttd-export.md)`);
  }
  const lengths = new Map<string, number>();
  const ids = feature ? idsOf(design, feature) : null;
  for (const [i, formation] of (design.openttd?.formations ?? []).entries()) {
    let parts = 0;
    for (const car of formation.cars) {
      const key = JSON.stringify(Object.entries(car.params).sort());
      if (!lengths.has(key)) lengths.set(key, carLength(car.params));
      parts += openttdPartCount(lengths.get(key)!);
    }
    const block = ids?.formations[i];
    if (block && parts > block.size) {
      throw new Error(`${design.id}: the formation "${formation.name}" has ${parts} OpenTTD parts, over the ${block.size} ids generator/openttdIds.json reserves for it: give it a new name (and a new block) (docs/site/openttd-export.md, "Ids")`);
    }
    if (parts > OPENTTD_MAX_PARTS) {
      throw new Error(`${design.id}: the formation "${formation.name}" has ${parts} OpenTTD parts, over the cap of ${OPENTTD_MAX_PARTS} (docs/site/openttd-export.md)`);
    }
  }
}

/** A vehicle's rider seat, measured on its built model (riderSeat.ts) in the yaw the game turns it by. */
export function vehicleSeat(design: ProceduralDesign, bytes: Uint8Array): Vec3 {
  const fields = catalogFields(design);
  return riderSeat(readTriangles(bytes), gameYaw(fields.category, fields.yaw));
}

/** Whether the build draws a design's thumbnail in the side view (a road or rail vehicle). */
export function designUsesSideView(id: string): boolean {
  const design = DESIGNS.get(id);
  if (!design) throw new Error(`no procedural model "${id}"`);
  return isSideViewCategory(catalogFields(design).category);
}

/** The procedural source tree of one design. Throws on an unknown id. */
export function designTree(id: string): SourceTree {
  const design = DESIGNS.get(id);
  if (!design) throw new Error(`no procedural model "${id}"`);
  return design.build().sourceTree(design.id, design.title);
}

/**
 * Throws when a tree file's text would exceed TREE_MAX_BYTES (Cloudflare's
 * per-asset limit), naming every such design, so the build fails rather than
 * the deploy. The cure is `sourceTree: false` on the design.
 */
export function checkTreeSizes(texts: ReadonlyMap<string, string>): void {
  const mib = (n: number): string => `${(n / 1048576).toFixed(1)} MiB`;
  const big = [...texts].map(([id, t]) => [id, Buffer.byteLength(t)] as const).filter(([, n]) => n > TREE_MAX_BYTES);
  if (big.length) {
    throw new Error(`source tree over the ${mib(TREE_MAX_BYTES)} asset limit (set sourceTree: false on the design): ${big.map(([id, n]) => `${id} ${mib(n)}`).join(", ")}`);
  }
}

/** Thrown when one or more designs would flicker; the message lists every overlap. */
export class ZFightingError extends Error {
  constructor(readonly found: ReadonlyMap<string, CoplanarOverlap[]>) {
    super(
      [
        "z-fighting faces (coplanar surfaces of different materials) - the model would flicker:",
        ...[...found].flatMap(([id, overlaps]) =>
          overlaps.map((o) =>
            `  ${id}: ${o.materials.join(" vs ")} on the plane n=(${o.normal.map((c) => c.toFixed(2)).join(", ")}) d=${o.offset.toFixed(2)}, ${o.area.toFixed(2)} m2`,
          ),
        ),
        "Give the shared surface one owner (see docs/models/skyscrapers.md, \"Flicker\").",
      ].join("\n"),
    );
    this.name = "ZFightingError";
  }
}

/** A design built for the export: its in-memory GLB and what the export reads of the model. */
interface BuiltDesign {
  design: ProceduralDesign;
  bytes: Uint8Array;
  triangles: number;
  tree: SourceTree | null;
  rig: VehicleRig | null;
}

/**
 * Builds `designs` (with their source trees when `withTree` says so) and checks
 * those `check` names: no z-fighting at any level, LOD, coarse and Max detail
 * inside their budgets. Throws before anything is written.
 */
function buildAll(designs: readonly ProceduralDesign[], check: (design: ProceduralDesign) => boolean, withTree: (design: ProceduralDesign) => boolean): BuiltDesign[] {
  const built = designs.map((design) => {
    const model = design.build();
    return {
      design,
      bytes: toGlb(design.id, model),
      // a vehicle's interior, hidden at rest, has a budget of its own (docs/models/interiors.md)
      triangles: model.exteriorTriangleCount(),
      tree: withTree(design) ? model.sourceTree(design.id, design.title) : null,
      rig: model.rig,
    };
  });
  const checked = built.filter((b) => check(b.design));
  const found = new Map<string, CoplanarOverlap[]>();
  for (const b of checked) {
    const overlaps = findCoplanarOverlaps(b.bytes);
    if (overlaps.length) found.set(b.design.id, overlaps);
  }
  if (found.size) throw new ZFightingError(found);
  for (const {design} of checked) {
    const low = buildLodModel(design);
    if (!low.triangleCount() || low.triangleCount() > lodBudget(design)) throw new Error(`${design.id}: invalid LOD triangle count ${low.triangleCount()}`);
    const overlaps = findCoplanarOverlaps(low.toGlb(design.id));
    if (overlaps.length) found.set(`${design.id} (LOD)`, overlaps);
    if (design.buildCoarse) {
      const coarse = design.buildCoarse();
      if (!coarse.triangleCount() || coarse.triangleCount() > COARSE_TRIANGLES) throw new Error(`${design.id}: invalid coarse triangle count ${coarse.triangleCount()}`);
      const flat = findCoplanarOverlaps(coarse.toGlb(design.id));
      if (flat.length) found.set(`${design.id} (coarse)`, flat);
    }
    if (design.buildMax) {
      const max = design.buildMax();
      if (!max.triangleCount() || max.triangleCount() > MAX_DETAIL_TRIANGLES) throw new Error(`${design.id}: invalid Max detail triangle count ${max.triangleCount()}`);
      const flat = findCoplanarOverlaps(max.toGlb(design.id));
      if (flat.length) found.set(`${design.id} (max)`, flat);
    }
  }
  if (found.size) throw new ZFightingError(found);
  return built;
}

export interface GeneratedModel {
  id: string;
  /** The design's build-cache key (buildCache.ts); null for a design with no source module, which is never cached. */
  key: string | null;
  /** The thumbnail's absolute path; null for a workshop draft, whose thumbnail the site renders in the browser (docs/site/workshop.md). */
  thumb: string | null;
  tree: string | null; // absolute path; null for a design without one (`sourceTree: false`)
  triangles: number;
  /** What the catalog lists of the built model: counts and bounding box (glbStats.ts). */
  stats: GlbStats;
  /** The model's rig (rig.ts), or null. */
  rig: VehicleRig | null;
  /** The frame of a side-view thumbnail (a road or rail vehicle's), or null for the three-quarter view. */
  side: SideFrame | null;
  /** A vehicle's rider seat (riderSeat.ts) in the model's frame, metres; null for anything else. */
  seat: Vec3 | null;
  /** What the JS bundle needs of the built models (jsModel.ts). */
  bundle: BundleFlags;
  /** True when the design was built and checked afresh: its inputs changed (or its cache entry is missing). */
  changed: boolean;
}

/** The build cache of an export folder: the committed build-cache/ for the repository's, one inside a test's own folder. */
export function cacheDirFor(dir: string): string {
  return path.resolve(dir) === EXPORT_DIR ? BUILD_CACHE_DIR : path.join(dir, ".build-cache");
}

/** Everything besides its source files the build of a design reads: part of its cache key. */
function keySettings(design: ProceduralDesign): unknown {
  const fields = catalogFields(design);
  return {
    fields,
    vehicle: VEHICLE_IDS.has(design.id),
    side: isSideViewCategory(fields.category),
    thumb: [THUMB_VERSION, THUMB_SIZE],
    caps: [COARSE_TRIANGLES, MAX_DETAIL_TRIANGLES],
  };
}

/** Every design's build-cache key, by id (null for one with no source module). */
export function designKeys(designs: readonly ProceduralDesign[], graph = new SourceGraph()): Map<string, string | null> {
  return new Map(designs.map((d) => [d.id, designKey(graph, d, DESIGN_SOURCE.get(d.id), keySettings(d))] as const));
}

/** Copies `from` to `to` unless `to` already holds the same bytes. */
function copyIfChanged(from: string, to: string): void {
  const bytes = fs.readFileSync(from);
  if (!fs.existsSync(to) || !bytes.equals(fs.readFileSync(to))) fs.writeFileSync(to, bytes);
}

/**
 * Writes every design's thumbnail and source tree into `dir`/thumbs and
 * `dir`/tree. A design whose build-cache key is unchanged (buildCache.ts,
 * docs/guide/build-cache.md) is not built at all: its facts come from the cache,
 * its thumbnail is copied from it and its tree file stays. Any other is built,
 * checked and measured, its thumbnail rendered into the cache (a confirmed
 * model's only: a workshop draft's is drawn by the site in the browser), and the
 * cache updated. Files of designs that no longer exist are removed, and so is an
 * old export's glb/ folder. Throws a ZFightingError, writing nothing, when any
 * design built would flicker.
 */
export function generateModels(
  dir = EXPORT_DIR,
  designs: readonly ProceduralDesign[] = [...DESIGNS.values()],
  cache = new BuildCache(cacheDirFor(dir)),
): GeneratedModel[] {
  const keys = designKeys(designs);
  const exportKeys = readExportKeys(dir);
  const thumbDir = path.join(dir, "thumbs");
  const treeDir = path.join(dir, TREE_DIR);
  const withThumb = new Set(designs.filter((d) => !isDraft(d.id)).map((d) => d.id));
  const withTree = new Set(designs.filter((d) => d.sourceTree !== false).map((d) => d.id));
  const treeFile = (id: string): string => path.join(treeDir, `${id}.json`);
  const cached = (d: ProceduralDesign) => cache.get(d.id, keys.get(d.id)!);
  const needsThumb = (d: ProceduralDesign) => withThumb.has(d.id) && (!cached(d) || !fs.existsSync(cache.thumb(d.id)));
  const needsTree = (d: ProceduralDesign) => {
    const key = keys.get(d.id)!;
    return withTree.has(d.id) && (!cached(d) || key === null || exportKeys.tree[d.id] !== key || !fs.existsSync(treeFile(d.id)));
  };
  // only what the cache cannot give is built; a design is checked when its facts are new
  const built = new Map(buildAll(designs.filter((d) => !cached(d) || needsThumb(d) || needsTree(d)), (d) => !cached(d), needsTree).map((b) => [b.design.id, b]));
  const treeTexts = new Map([...built.values()].filter((b) => b.tree).map((b) => [b.design.id, `${JSON.stringify(b.tree)}\n`]));
  checkTreeSizes(treeTexts); // throws before anything touches the disk, too
  fs.mkdirSync(thumbDir, { recursive: true });
  fs.mkdirSync(treeDir, { recursive: true });
  fs.mkdirSync(path.dirname(cache.thumb("x")), { recursive: true });
  fs.rmSync(path.join(dir, "glb"), { recursive: true, force: true });
  // an older export's thumbnail hashes, from before the build cache
  for (const old of [".sources.json", ".version"]) fs.rmSync(path.join(thumbDir, old), { force: true });
  const treeKeys = new Map<string, string>();
  const out: GeneratedModel[] = [];
  for (const design of designs) {
    const key = keys.get(design.id)!;
    const b = built.get(design.id);
    let facts = cached(design);
    const changed = !facts;
    const sideView = isSideViewCategory(catalogFields(design).category);
    if (!facts) {
      facts = {
        key: key ?? "",
        triangles: b!.triangles,
        stats: glbStats(b!.bytes),
        rig: b!.rig,
        side: sideView ? glbSideFrame(b!.bytes) : null,
        seat: VEHICLE_IDS.has(design.id) ? vehicleSeat(design, b!.bytes) : null,
        bundle: bundleFlags(design, posable(b!.rig)),
        extents: {},
      };
      if (key !== null) cache.set(design.id, facts);
    }
    let thumb: string | null = null;
    if (withThumb.has(design.id)) {
      thumb = path.join(thumbDir, `${design.id}.png`);
      if (changed || needsThumb(design)) {
        const png = sideView ? renderGlbSideThumb(b!.bytes).png : renderGlbThumb(b!.bytes, THUMB_SIZE);
        fs.writeFileSync(cache.thumb(design.id), PNG.sync.write(png));
      }
      copyIfChanged(cache.thumb(design.id), thumb);
    }
    let tree: string | null = null;
    if (withTree.has(design.id)) {
      tree = treeFile(design.id);
      const text = treeTexts.get(design.id);
      if (text !== undefined) writeIfChanged(tree, text);
      if (key !== null) treeKeys.set(design.id, key);
    }
    out.push({ id: design.id, key, thumb, tree, triangles: facts.triangles, stats: facts.stats, rig: facts.rig, side: facts.side, seat: facts.seat, bundle: facts.bundle, changed });
  }
  writeExportKeys(dir, "tree", treeKeys);
  cache.save(new Set(designs.map((d) => d.id)), withThumb);
  for (const [sub, ext, keep] of [[thumbDir, ".png", withThumb], [treeDir, ".json", withTree]] as const) {
    for (const name of fs.readdirSync(sub)) {
      if (name.endsWith(ext) && !keep.has(name.slice(0, -ext.length))) fs.rmSync(path.join(sub, name));
    }
  }
  return out;
}

/** How many designs are bundled at once: esbuild works off the main thread. */
const BUNDLE_CONCURRENCY = 8;

/**
 * Writes `dir`/js/<id>.js for every design and removes the files of designs that
 * no longer exist. `models` (generateModels' output) gives each design's
 * build-cache key and bundle flags: a file written for the same key is kept as it
 * is, without bundling, and a bundle needs no build. A file is rewritten only
 * when its text changed. Returns each file's text by id.
 */
export async function generateJsModels(
  dir = EXPORT_DIR,
  designs: readonly ProceduralDesign[] = [...DESIGNS.values()],
  models?: ReadonlyMap<string, Pick<GeneratedModel, "key" | "bundle">>,
): Promise<Map<string, string>> {
  const jsDir = path.join(dir, JS_DIR);
  fs.mkdirSync(jsDir, { recursive: true });
  const written = readExportKeys(dir).js;
  const texts = new Array<string>(designs.length);
  const jsKeys = new Map<string, string>();
  let next = 0;
  const worker = async (): Promise<void> => {
    while (next < designs.length) {
      const i = next++;
      const design = designs[i]!;
      const source = DESIGN_SOURCE.get(design.id);
      if (!source) throw new Error(`no source module for design "${design.id}"`);
      const known = models?.get(design.id);
      const file = path.join(jsDir, `${design.id}.js`);
      if (known?.key && written[design.id] === known.key && fs.existsSync(file)) {
        texts[i] = fs.readFileSync(file, "utf8");
      } else {
        texts[i] = await bundleDesign(design, source, known?.bundle);
        writeIfChanged(file, texts[i]!);
      }
      if (known?.key) jsKeys.set(design.id, known.key);
    }
  };
  await Promise.all(Array.from({ length: BUNDLE_CONCURRENCY }, worker));
  const out = new Map(designs.map((d, i) => [d.id, texts[i]!] as const));
  writeExportKeys(dir, "js", jsKeys);
  for (const name of fs.readdirSync(jsDir)) {
    if (name.endsWith(".js") && !out.has(name.slice(0, -3))) fs.rmSync(path.join(jsDir, name));
  }
  return out;
}

/** Every file under `dir`, as sorted forward-slash paths relative to it. */
function listFiles(dir: string): string[] {
  if (!fs.existsSync(dir)) return [];
  return fs
    .readdirSync(dir, { recursive: true, encoding: "utf8" })
    .map((p) => p.split(path.sep).join("/"))
    .filter((p) => fs.statSync(path.join(dir, p)).isFile())
    .sort();
}

/**
 * A design's source images in name order: its name under refs/<id>/ (a second or
 * later folder's files under <folder>/) and the absolute path of the file in
 * assets/. The export copies them (generateReferences); `pnpm dev` serves them
 * from assets/ as they are (devExport.ts).
 */
export function designReferenceFiles(design: ProceduralDesign, assetsDir = ASSETS_DIR): Array<{ name: string; file: string }> {
  const out: Array<{ name: string; file: string }> = [];
  const folders = typeof design.references === "string" ? [design.references] : (design.references ?? []);
  for (const [k, folder] of folders.entries()) {
    const src = path.join(assetsDir, folder);
    for (const file of listFiles(src)) {
      const name = k === 0 ? file : `${folder}/${file}`;
      if (REFERENCE_EXTENSIONS.some((ext) => name.toLowerCase().endsWith(ext))) out.push({ name, file: path.join(src, file) });
    }
  }
  return out;
}

/**
 * Copies each design's source images (assets/<references>/, any depth, the
 * REFERENCE_EXTENSIONS; a second or later folder's files under <folder>/) to
 * `dir`/refs/<id>/, rewriting a file only when its
 * bytes changed, and removes every other file under `dir`/refs. Returns each
 * design's images in name order; a design without references gets none.
 */
export function generateReferences(
  dir = EXPORT_DIR,
  designs: readonly ProceduralDesign[] = [...DESIGNS.values()],
  assetsDir = ASSETS_DIR,
): Map<string, ReferenceImage[]> {
  const refsDir = path.join(dir, REFS_DIR);
  const out = new Map<string, ReferenceImage[]>();
  const keep = new Set<string>();
  for (const design of designs) {
    const images: ReferenceImage[] = [];
    for (const { name, file } of designReferenceFiles(design, assetsDir)) {
      const bytes = fs.readFileSync(file);
      const rel = `${design.id}/${name}`;
      const target = path.join(refsDir, rel);
      fs.mkdirSync(path.dirname(target), { recursive: true });
      if (!fs.existsSync(target) || !bytes.equals(fs.readFileSync(target))) fs.writeFileSync(target, bytes);
      keep.add(rel);
      images.push({ name, url: `${REFS_DIR}/${rel}`, bytes: bytes.length });
    }
    out.set(design.id, images);
  }
  for (const rel of listFiles(refsDir)) if (!keep.has(rel)) fs.rmSync(path.join(refsDir, rel));
  // empty folders left by removed files, deepest first
  const dirs = fs.existsSync(refsDir) ? fs.readdirSync(refsDir, { recursive: true, encoding: "utf8" }) : [];
  for (const sub of dirs.sort().reverse()) {
    const p = path.join(refsDir, sub);
    if (fs.statSync(p).isDirectory() && fs.readdirSync(p).length === 0) fs.rmdirSync(p);
  }
  return out;
}

/**
 * The whole export: the models, then the meta.json files and the site's
 * catalog.json. `designs` narrows it to some designs, every file listing only
 * those and legacy-models.json (which maps onto the whole catalog) left out --
 * the tests export a few; the build exports them all.
 */
export async function buildExport(
  dir = EXPORT_DIR,
  designs: readonly ProceduralDesign[] = [...DESIGNS.values()],
): Promise<{ models: GeneratedModel[]; catalog: ModelCatalog; js: Map<string, string> }> {
  const cache = new BuildCache(cacheDirFor(dir));
  const models = generateModels(dir, designs, cache);
  const keyOf = new Map(models.map((m) => [m.id, m.key] as const));
  const js = await generateJsModels(dir, designs, new Map(models.map((m) => [m.id, m] as const)));
  const refs = generateReferences(dir, designs);
  // the game's meta files list only the catalog's models: a draft stays in the workshop (workshop.ts)
  const chosen = (list: readonly ProceduralDesign[]) => list.filter((d) => designs.includes(d) && !isDraft(d.id));
  fs.writeFileSync(path.join(dir, META_FILE), `${JSON.stringify(exportMeta(chosen(BUILDINGS)), null, 2)}\n`);
  fs.writeFileSync(path.join(dir, VILLAGE_META_FILE), `${JSON.stringify(exportMeta(chosen(VILLAGE_DESIGNS)), null, 2)}\n`);
  const rigs = new Map(models.flatMap((m) => (m.rig ? [[m.id, m.rig] as const] : [])));
  const sides = new Map(models.flatMap((m) => (m.side ? [[m.id, m.side] as const] : [])));
  const seats = new Map(models.flatMap((m) => (m.seat ? [[m.id, m.seat] as const] : [])));
  fs.writeFileSync(path.join(dir, VEHICLE_META_FILE), `${JSON.stringify(exportVehicleMeta(chosen(ALL_VEHICLES), rigs, sides, seats), null, 2)}\n`);
  const bounds = new Map(models.map((m) => [m.id, { min: m.stats.min, max: m.stats.max }] as const));
  fs.writeFileSync(path.join(dir, PROPS_META_FILE), `${JSON.stringify(exportPropMeta(chosen(PROP_DESIGNS), bounds, FAR_PROPS), null, 2)}\n`);
  fs.writeFileSync(path.join(dir, CHARACTERS_META_FILE), `${JSON.stringify(exportCharacterMeta(chosen(CHARACTER_DESIGNS), bounds), null, 2)}\n`);
  // the woods types and the tree species they draw from (woodsExport.ts); only a whole export has them
  if (designs.length === DESIGNS.size) await generateWoods(dir);
  // the set registry and its landed modules (sets/setsExport.ts), and the exported
  // text in every language (text.ts); likewise only a whole export has them
  if (designs.length === DESIGNS.size) {
    await generateSets(dir);
    generateText(dir);
    generateSurfaces(dir);
  }
  fs.writeFileSync(path.join(dir, "industry-migration.json"), `${JSON.stringify({ version: 1, entries: INDUSTRY_MIGRATION }, null, 2)}\n`);
  // the extents measured on built models are cached with the design's facts (buildCache.ts)
  const extents = (design: ProceduralDesign, params: ParamValues, measure: () => number[]): number[] =>
    cache.extents(design.id, keyOf.get(design.id) ?? null, params, measure);
  const measured = (design: ProceduralDesign, params: ParamValues, modelId = design.id): number[] => {
    const stats = glbStats(toGlb(modelId, design.build(params)));
    return stats.max.map((v, i) => v - stats.min[i]!);
  };
  for (const design of designs) checkOpenttdDesign(design, (params) => extents(design, params, () => measured(design, params))[0]!);
  // every model soundTable.ts gives a sound must exist (docs/models/sounds.md)
  if (designs.length === DESIGNS.size) {
    const unknown = unknownTableIds(designs);
    if (unknown.length) throw new Error(`generator/soundTable.ts names no such model: ${unknown.join(", ")}`);
    const unconfirmed = unknownCatalogIds(DESIGNS.keys());
    if (unconfirmed.length) throw new Error(`generator/catalogModels.json names no such model: ${unconfirmed.join(", ")}`);
    const badLinks = linkTableProblems(DESIGNS.keys());
    if (badLinks.length) throw new Error(`generator/linkTable.ts: ${badLinks.join("; ")}`);
  }
  const catalog: ModelCatalog = {
    version: 1,
    records: designs.map((design) => {
      const built = models.find((m) => m.id === design.id)!;
      const jsText = js.get(design.id)!;
      const record = catalogRecord(listedEntry(metaEntry(design, catalogFields(design), built.rig, built.side, built.seat), design, BUILDINGS.includes(design) || VILLAGE_DESIGNS.includes(design)), {
        ...built.stats,
        jsBytes: Buffer.byteLength(jsText),
        jsGzipBytes: gzipSize(jsText),
        jsHash: crypto.createHash("sha256").update(jsText).digest("hex").slice(0, 16),
        thumbBytes: built.thumb ? fs.statSync(built.thumb).size : 0,
      }, refs.get(design.id), catalogOpenttd(design, catalogFields(design)));
      return { ...record, ...airframeField(design.id), ...(design.buildCoarse ? { coarse: true } : {}), ...(design.buildMax ? { maxDetail: true } : {}), ...(design.sourceTree === false ? { noSourceTree: true } : {}) };
    }),
  };
  // the legacy table maps old ids onto the whole catalog, so a narrowed export has none
  if (designs.length === DESIGNS.size) {
    const table = buildLegacyMapping(DESIGNS, (design, params, modelId) => extents(design, params, () => measureModel(design, params, modelId)));
    fs.writeFileSync(path.join(dir, "legacy-models.json"), `${JSON.stringify(table, null, 2)}\n`);
  }
  await bundleRuntime({ entryPoints:[path.join(REPO_ROOT,"generator/modelReference.ts")], outfile:path.join(dir,"model-reference.js"), bundle:true, format:"esm", platform:"neutral", target:"es2022" });
  fs.writeFileSync(path.join(dir, CATALOG_FILE), `${JSON.stringify(catalog, null, 2)}\n`);
  // the extents measured since generateModels saved it
  cache.save(new Set(designs.map((d) => d.id)), new Set(designs.filter((d) => !isDraft(d.id)).map((d) => d.id)));
  return { models, catalog, js };
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  let models: GeneratedModel[];
  let catalog: ModelCatalog;
  try {
    ({ models, catalog } = await buildExport());
  } catch (e) {
    if (!(e instanceof ZFightingError)) throw e;
    console.error(e.message);
    process.exit(1);
  }
  for (const m of models) {
    console.log(`${m.id.padEnd(24)} ${String(m.triangles).padStart(5)} tris ${m.changed ? "(built)" : "(cached)"}`);
  }
  console.log(`\n${models.filter((m) => m.changed).length} of ${models.length} designs built; the others came from build-cache/`);
  console.log(`\n${"model".padEnd(24)} ${"JS".padStart(9)} ${"JS gz".padStart(9)}`);
  for (const r of catalog.records) {
    const kb = (n: number): string => `${(n / 1024).toFixed(1)} KB`.padStart(9);
    console.log(`${r.id.padEnd(24)} ${kb(r.jsBytes)} ${kb(r.jsGzipBytes)}`);
  }
  console.log(`\nExport: ${path.relative(process.cwd(), EXPORT_DIR) || "."} (${models.length} models)`);
}
